void strided_saxpy_cuda(REAL* x, REAL* y, long n, int stride, REAL a) {
    REAL *d_x, *d_y;
    cudaMalloc(&d_x, n*sizeof(REAL));
    cudaMalloc(&d_y, n*sizeof(REAL));

    cudaMemcpy(d_x, x, n*sizeof(REAL), cudaMemcpyHostToDevice);
    cudaMemcpy(d_y, y, n*sizeof(REAL), cudaMemcpyHostToDevice);

    long m = (n + stride - 1) / stride;   /* 被触碰的元素个数 */
    long grid = (m + 255) / 256;          /* 向上取整到 256 线程的块 */

    strided_saxpy_cudakernel_warmingup<<<grid, 256>>>(d_x, d_y, n, stride, a);
    cudaDeviceSynchronize();

    if (stride == 1)
        strided_saxpy_cudakernel_stride1<<<grid, 256>>>(d_x, d_y, n, a);
    else
        strided_saxpy_cudakernel_strided<<<grid, 256>>>(d_x, d_y, n, stride, a);
    cudaDeviceSynchronize();

    cudaMemcpy(y, d_y, n*sizeof(REAL), cudaMemcpyDeviceToHost);
    cudaFree(d_x);
    cudaFree(d_y);
}
